CREATE TABLE projects (id BIGINT NOT NULL, tenant_id BIGINT NOT NULL, slug VARCHAR(80) NOT NULL, PRIMARY KEY (tenant_id, id), UNIQUE KEY uq_projects_tenant_slug (tenant_id, slug)); CREATE TABLE tasks (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, project_id BIGINT NOT NULL, CONSTRAINT fk_tasks_project_tenant FOREIGN KEY (tenant_id, project_id) REFERENCES projects(tenant_id, id));
